    75→    init(roomListService: RoomListServiceProtocol,
    76→         room: RoomProtocol,
    77→         appSettings: AppSettings) async throws {
    78→        self.roomListService = roomListService
    79→        self.room = room
    80→        self.appSettings = appSettings
    81→        
    82→        infoSubject = try await .init(RoomInfoProxy(roomInfo: room.roomInfo()))
    83→        
    84→        timeline = try await TimelineProxy(timeline: room.timelineWithConfiguration(configuration: .init(focus: .live(hideThreadedEvents: appSettings.threadsEnabled),
    85→                                                                                                         filter: .eventTypeFilter(filter: excludedEventsFilter),
    86→                                                                                                         internalIdPrefix: nil,
    87→                                                                                                         dateDividerMode: .daily,
    88→                                                                                                         trackReadReceipts: .messageLikeEvents,
    89→                                                                                                         reportUtds: true)),
    90→                                           kind: .live)
    91→        
    92→        Task {
    93→            await updateMembers()
    94→            
    95→            // Try to update the encryption state if it's unknown.
    96→            // This is an edge case as sliding sync should pass
    97→            // that information down to the room info on the rust side.
    98→            if room.encryptionState() == .unknown {
    99→                MXLog.error("The encryption state should almost always be known.")
   100→                _ = try? await room.latestEncryptionState()
   101→            }
   102→        }
   103→    }
