   105→    func subscribeForUpdates() async {
   106→        guard !subscribedForUpdates else {
   107→            MXLog.warning("Room already subscribed for updates")
   108→            return
   109→        }
   110→        
   111→        subscribedForUpdates = true
   112→
   113→        do {
   114→            try await roomListService.subscribeToRooms(roomIds: [id])
   115→        } catch {
   116→            MXLog.error("Failed subscribing to room with error: \(error)")
   117→        }
   118→        
   119→        await timeline.subscribeForUpdates()
   120→        
   121→        Task {
   122→            subscribeToRoomInfoUpdates()
   123→            
   124→            subscribeToTypingNotifications()
   125→            
   126→            await subscribeToKnockRequests()
   127→            
   128→            if infoPublisher.value.isEncrypted {
   129→                await subscribeToIdentityStatusChanges()
   130→            }
   131→        }
   132→    }
