   145→    func timelineFocusedOnEvent(eventID: String, numberOfEvents: UInt16) async -> Result<TimelineProxyProtocol, RoomProxyError> {
   146→        do {
   147→            let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: .event(eventId: eventID,
   148→                                                                                                          numContextEvents: numberOfEvents,
   149→                                                                                                          hideThreadedEvents: appSettings.threadsEnabled),
   150→                                                                                            filter: .all,
   151→                                                                                            internalIdPrefix: UUID().uuidString,
   152→                                                                                            dateDividerMode: .daily,
   153→                                                                                            trackReadReceipts: .disabled,
   154→                                                                                            reportUtds: true))
   155→            
   156→            return .success(TimelineProxy(timeline: sdkTimeline, kind: .detached))
   157→        } catch let error as FocusEventError {
   158→            switch error {
   159→            case .InvalidEventId(_, let error):
   160→                MXLog.error("Invalid event \(eventID) Error: \(error)")
   161→                return .failure(.eventNotFound)
   162→            case .EventNotFound:
   163→                MXLog.error("Event \(eventID) not found.")
   164→                return .failure(.eventNotFound)
   165→            case .Other(let message):
   166→                MXLog.error("Failed to create a timeline focussed on event \(eventID) Error: \(message)")
   167→                return .failure(.sdkError(error))
   168→            }
   169→        } catch {
   170→            MXLog.error("Unexpected error: \(error)")
   171→            return .failure(.sdkError(error))
   172→        }
   173→    }
