   204→    func messageFilteredTimeline(focus: TimelineFocus,
   205→                                 allowedMessageTypes: [TimelineAllowedMessageType],
   206→                                 presentation: TimelineKind.MediaPresentation) async -> Result<any TimelineProxyProtocol, RoomProxyError> {
   207→        do {
   208→            let rustFocus: MatrixRustSDK.TimelineFocus = switch focus {
   209→            case .live: .live(hideThreadedEvents: false)
   210→            case .eventID(let eventID): .event(eventId: eventID, numContextEvents: 100, hideThreadedEvents: false)
   211→            case .thread(let eventID): .thread(rootEventId: eventID)
   212→            case .pinned: .pinnedEvents(maxEventsToLoad: 100, maxConcurrentRequests: 10)
   213→            }
   214→            
   215→            let rustMessageTypes: [MatrixRustSDK.RoomMessageEventMessageType] = allowedMessageTypes.map {
   216→                switch $0 {
   217→                case .audio: .audio
   218→                case .file: .file
   219→                case .image: .image
   220→                case .video: .video
   221→                }
   222→            }
   223→            
   224→            let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: rustFocus,
   225→                                                                                            filter: .onlyMessage(types: rustMessageTypes),
   226→                                                                                            internalIdPrefix: nil,
   227→                                                                                            dateDividerMode: .monthly,
   228→                                                                                            trackReadReceipts: .disabled,
   229→                                                                                            reportUtds: true))
   230→            
   231→            let timeline = TimelineProxy(timeline: sdkTimeline, kind: .media(presentation))
   232→            await timeline.subscribeForUpdates()
   233→            
   234→            return .success(timeline)
   235→        } catch {
   236→            MXLog.error("Failed retrieving media events timeline with error: \(error)")
   237→            return .failure(.sdkError(error))
   238→        }
   239→    }
