   241→    func pinnedEventsTimeline() async -> Result<TimelineProxyProtocol, RoomProxyError> {
   242→        // Check if is already available.
   243→        if let innerPinnedEventsTimeline {
   244→            return .success(innerPinnedEventsTimeline)
   245→            // Otherwise check if there is already a task loading it, and wait for it.
   246→        } else if let innerPinnedEventsTimelineTask {
   247→            return await innerPinnedEventsTimelineTask.value
   248→        } else { // Else create and store a new task to load it and wait for it.
   249→            let task = Task<Result<TimelineProxyProtocol, RoomProxyError>, Never> { [weak self] in
   250→                guard let self else {
   251→                    return .failure(.failedCreatingPinnedTimeline)
   252→                }
   253→                
   254→                do {
   255→                    let sdkTimeline = try await room.timelineWithConfiguration(configuration: .init(focus: .pinnedEvents(maxEventsToLoad: 100, maxConcurrentRequests: 10),
   256→                                                                                                    filter: .all,
   257→                                                                                                    internalIdPrefix: nil,
   258→                                                                                                    dateDividerMode: .daily,
   259→                                                                                                    trackReadReceipts: .disabled,
   260→                                                                                                    reportUtds: true))
   261→                    
   262→                    let timeline = TimelineProxy(timeline: sdkTimeline, kind: .pinned)
   263→                    
   264→                    await timeline.subscribeForUpdates()
   265→                    innerPinnedEventsTimeline = timeline
   266→                    return .success(timeline)
   267→                } catch {
   268→                    MXLog.error("Failed creating pinned events timeline with error: \(error)")
   269→                    return .failure(.sdkError(error))
   270→                }
   271→            }
   272→            
   273→            innerPinnedEventsTimelineTask = task
   274→            return await task.value
   275→        }
   276→    }
