   318→    func updateMembers() async {
   319→        // We always update members first using the no sync API in case internet is not readily available
   320→        // To get the members stored on disk first, this API call is very fast.
   321→        do {
   322→            let membersNoSyncIterator = try await room.membersNoSync()
   323→            if let members = membersNoSyncIterator.nextChunk(chunkSize: membersNoSyncIterator.len()) {
   324→                membersSubject.value = members.map(RoomMemberProxy.init)
   325→            }
   326→        } catch {
   327→            MXLog.error("Failed updating members using no sync API: \(error)")
   328→        }
   329→        
   330→        do {
   331→            // Then we update members using the sync API, this is slower but will get us the latest members
   332→            let membersIterator = try await room.members()
   333→            if let members = membersIterator.nextChunk(chunkSize: membersIterator.len()) {
   334→                membersSubject.value = members.map(RoomMemberProxy.init)
   335→            }
   336→        } catch {
   337→            MXLog.error("Failed updating members using sync API: \(error)")
   338→        }
   339→    }
