    23→    private var pinnedEventsTimelineItemProvider: TimelineItemProviderProtocol? {
    24→        didSet {
    25→            guard let pinnedEventsTimelineItemProvider else {
    26→                return
    27→            }
    28→            
    29→            state.pinnedEventsActionState = .loaded(numberOfItems: pinnedEventsTimelineItemProvider.itemProxies.filter(\.isEvent).count)
    30→            
    31→            pinnedEventsTimelineItemProvider.updatePublisher
    32→                // When pinning or unpinning an item, the timeline might return empty for a short while, so we need to debounce it to prevent weird UI behaviours like the banner disappearing
    33→                .debounce(for: .milliseconds(100), scheduler: DispatchQueue.main)
    34→                .sink { [weak self] updatedItems, _ in
    35→                    self?.state.pinnedEventsActionState = .loaded(numberOfItems: updatedItems.filter(\.isEvent).count)
    36→                }
    37→                .store(in: &cancellables)
    38→        }
    39→    }
