   171→    private func processTapToLeave() {
   172→        guard !roomProxy.infoPublisher.value.isSpace else {
   173→            Task { await processLeaveSpace() }
   174→            return
   175→        }
   176→        
   177→        guard state.joinedMembersCount > 1 else {
   178→            state.bindings.leaveRoomAlertItem = LeaveRoomAlertItem(roomID: roomProxy.id,
   179→                                                                   isDM: roomProxy.isDirectOneToOneRoom,
   180→                                                                   state: roomProxy.infoPublisher.value.isPrivate ?? true ? .empty : .public)
   181→            return
   182→        }
   183→        
   184→        if !roomProxy.isDirectOneToOneRoom, state.accountOwner?.role.isOwner == true {
   185→            var isLastOwner = true
   186→            for member in roomProxy.membersPublisher.value where member.userID != roomProxy.ownUserID && member.membership == .join {
   187→                if member.role.isOwner {
   188→                    isLastOwner = false
   189→                    break
   190→                }
   191→            }
   192→            
   193→            if isLastOwner {
   194→                state.bindings.alertInfo = .init(id: .lastOwner,
   195→                                                 title: L10n.leaveRoomAlertSelectNewOwnerTitle,
   196→                                                 message: L10n.leaveRoomAlertSelectNewOwnerSubtitle,
   197→                                                 primaryButton: .init(title: L10n.actionCancel, role: .cancel, action: nil),
   198→                                                 secondaryButton: .init(title: L10n.leaveRoomAlertSelectNewOwnerAction, role: .destructive) { [weak self] in
   199→                                                     self?.actionsSubject.send(.transferOwnership)
   200→                                                 })
   201→                return
   202→            }
   203→        }
   204→        
   205→        state.bindings.leaveRoomAlertItem = LeaveRoomAlertItem(roomID: roomProxy.id,
   206→                                                               isDM: roomProxy.isDirectOneToOneRoom,
   207→                                                               state: roomProxy.infoPublisher.value.isPrivate ?? true ? .private : .public)
   208→    }
