   210→    private func processLeaveSpace() async {
   211→        switch await userSession.clientProxy.spaceService.leaveSpace(spaceID: roomProxy.id) {
   212→        case .success(let leaveHandle):
   213→            let leaveSpaceViewModel = LeaveSpaceViewModel(spaceName: state.details.name ?? state.details.id,
   214→                                                          canEditRolesAndPermissions: state.canEditRolesOrPermissions,
   215→                                                          leaveHandle: leaveHandle,
   216→                                                          userIndicatorController: userIndicatorController,
   217→                                                          mediaProvider: userSession.mediaProvider)
   218→            leaveSpaceViewModel.actions.sink { [weak self] action in
   219→                guard let self else { return }
   220→                switch action {
   221→                case .didCancel:
   222→                    state.bindings.leaveSpaceViewModel = nil
   223→                case .presentRolesAndPermissions:
   224→                    state.bindings.leaveSpaceViewModel = nil
   225→                    actionsSubject.send(.requestRolesAndPermissionsPresentation)
   226→                case .didLeaveSpace:
   227→                    state.bindings.leaveSpaceViewModel = nil
   228→                    actionsSubject.send(.leftRoom)
   229→                }
   230→            }
   231→            .store(in: &cancellables)
   232→            
   233→            state.bindings.leaveSpaceViewModel = leaveSpaceViewModel
   234→        case .failure:
   235→            userIndicatorController.submitIndicator(.init(title: L10n.errorUnknown))
   236→        }
   237→    }
