   239→    private func setupRoomSubscription() {
   240→        roomProxy.infoPublisher
   241→            .receive(on: DispatchQueue.main)
   242→            .sink { [weak self] roomInfo in
   243→                self?.updateRoomInfo(roomInfo)
   244→            }
   245→            .store(in: &cancellables)
   246→        
   247→        roomProxy.knockRequestsStatePublisher
   248→            .map { requestsState in
   249→                guard case let .loaded(requests) = requestsState else {
   250→                    return 0
   251→                }
   252→                return requests.count
   253→            }
   254→            .removeDuplicates()
   255→            .throttle(for: .milliseconds(100), scheduler: DispatchQueue.main, latest: true)
   256→            .weakAssign(to: \.state.knockRequestsCount, on: self)
   257→            .store(in: &cancellables)
   258→        
   259→        roomProxy.membersPublisher.combineLatest(roomProxy.identityStatusChangesPublisher)
   260→            .sink { [weak self] _ in
   261→                Task { await self?.updateMemberIdentityVerificationStates() }
   262→            }
   263→            .store(in: &cancellables)
   264→    }
