   266→    private func updateRoomInfo(_ roomInfo: RoomInfoProxyProtocol) {
   267→        state.isEncrypted = roomInfo.isEncrypted
   268→        state.isDirect = roomInfo.isDirect
   269→        state.bindings.isFavourite = roomInfo.isFavourite
   270→        
   271→        state.joinedMembersCount = roomInfo.joinedMembersCount
   272→        
   273→        state.details = roomProxy.details
   274→        
   275→        let topic = attributedStringBuilder.fromPlain(roomInfo.topic)
   276→        state.topic = topic
   277→        state.topicSummary = topic?.unattributedStringByReplacingNewlinesWithSpaces()
   278→        
   279→        switch roomInfo.joinRule {
   280→        case .knock, .knockRestricted:
   281→            state.isKnockableRoom = true
   282→        default:
   283→            state.isKnockableRoom = false
   284→        }
   285→        
   286→        if let powerLevels = roomInfo.powerLevels {
   287→            state.canEditRoomName = powerLevels.canOwnUser(sendStateEvent: .roomName)
   288→            state.canEditRoomTopic = powerLevels.canOwnUser(sendStateEvent: .roomTopic)
   289→            state.canEditRoomAvatar = powerLevels.canOwnUser(sendStateEvent: .roomAvatar)
   290→            state.canInviteUsers = powerLevels.canOwnUserInvite()
   291→            state.canKickUsers = powerLevels.canOwnUserKick()
   292→            state.canBanUsers = powerLevels.canOwnUserBan()
   293→            state.canJoinCall = powerLevels.canOwnUserJoinCall()
   294→            state.canEditRolesOrPermissions = powerLevels.canOwnUserEditRolesAndPermissions()
   295→            state.canEditSecurityAndPrivacy = powerLevels.canOwnUserEditSecurityAndPrivacy(isSpace: roomInfo.isSpace,
   296→                                                                                           joinRule: roomInfo.joinRule)
   297→        }
   298→    }
