   300→    private func fetchMembersIfNeeded() async {
   301→        roomProxy.membersPublisher
   302→            .receive(on: DispatchQueue.main)
   303→            .sink { [weak self, ownUserID = roomProxy.ownUserID] members in
   304→                guard let self else { return }
   305→                
   306→                if let accountOwner = members.first(where: { $0.userID == ownUserID }) {
   307→                    self.state.accountOwner = .init(withProxy: accountOwner)
   308→                }
   309→                
   310→                guard roomProxy.isDirectOneToOneRoom else {
   311→                    return
   312→                }
   313→                
   314→                if let dmRecipient = members.first(where: { $0.userID != ownUserID }) {
   315→                    self.state.dmRecipientInfo = .init(member: .init(withProxy: dmRecipient))
   316→                    
   317→                    Task { await self.updateMemberIdentityVerificationStates() }
   318→                }
   319→            }
   320→            .store(in: &cancellables)
   321→        
   322→        await roomProxy.updateMembers()
