   277→        let hasNoRooms = roomSummaryProviderState.isLoaded && roomSummaryProviderState.totalNumberOfRooms == 0
   278→        
   279→        var roomListMode = state.roomListMode
   280→        if isLoadingData {
   281→            roomListMode = .skeletons
   282→        } else if hasNoRooms {
   283→            roomListMode = .empty
   284→        } else {
   285→            roomListMode = .rooms
   286→        }
   287→        
   288→        guard roomListMode != state.roomListMode else {
   289→            return
   290→        }
   291→        
   292→        if roomListMode == .rooms, state.roomListMode == .skeletons {
   293→            analyticsService.signpost.endFirstRooms()
